using System.Reflection;
using System.Reflection.Metadata;
using System.Reflection.PortableExecutable;

namespace PaymentAuthorization.ArchitectureTest;

/// <summary>Guards the dependency rule: Domain ← Application ← Infrastructure. Inner layers must not
/// reference outer layers or technical (I/O, network, database) types.</summary>
public class LayerDependencyTests
{
    private const string Domain = "PaymentAuthorization.Domain";
    private const string Application = "PaymentAuthorization.Application";
    private const string Infrastructure = "PaymentAuthorization.Infrastructure";

    private static readonly string[] TechnicalNamespaces =
    [
        "System.IO", "System.Net", "System.Data", "System.Diagnostics.Process",
        "System.Security.Cryptography.X509Certificates", "Microsoft.Data", "Microsoft.EntityFrameworkCore",
        "Microsoft.Extensions.Http", "Microsoft.AspNetCore",
    ];

    public static TheoryData<string, string[]> Rules => new()
    {
        { Domain, [Application, Infrastructure] },
        { Application, [Infrastructure] },
    };

    [Theory]
    [MemberData(nameof(Rules))]
    public void Layer_does_not_reference_outer_layers(string layer, string[] forbidden)
    {
        var (assemblies, _) = ReadReferences(layer);
        Assert.Empty(assemblies.Where(a => forbidden.Contains(a)));
    }

    [Theory]
    [InlineData(Domain)]
    [InlineData(Application)]
    public void Business_layer_does_not_use_technical_types(string layer)
    {
        var (_, namespaces) = ReadReferences(layer);
        var violations = namespaces
            .Where(n => TechnicalNamespaces.Any(t => n == t || n.StartsWith(t + ".")))
            .Distinct().Order();
        Assert.Empty(violations);
    }

    private static (List<string> Assemblies, List<string> Namespaces) ReadReferences(string assemblyName)
    {
        var path = Assembly.Load(assemblyName).Location;
        using var pe = new PEReader(File.OpenRead(path));
        var md = pe.GetMetadataReader();
        var assemblies = md.AssemblyReferences.Select(h => md.GetString(md.GetAssemblyReference(h).Name)).ToList();
        var namespaces = md.TypeReferences
            .Select(h => md.GetString(md.GetTypeReference(h).Namespace))
            .Where(n => n.Length > 0).ToList();
        return (assemblies, namespaces);
    }
}
